export interface CustomFontFace {
	base64: string;
	format: "opentype" | "woff2" | "truetype";
	style: "normal" | "italic";
	/** Fixed weight for a static face (e.g. Courier Prime Bold = 700). When omitted, the face covers weightMin–weightMax. */
	weight?: number;
}

export interface CustomFontEntry {
	id:
		| "alan-sans"
		| "caveat"
		| "courier-prime"
		| "exo-2"
		| "fredoka"
		| "grenze"
		| "ibm-plex-sans-var"
		| "libre-baskerville"
		| "nunito"
		| "playpen-sans"
		| "sn-pro";
	cssFontFamily: string; // name registered via FontFace and used in font-family CSS
	label: string; // shown in the settings dropdown
	weightMin: number; // native weight range this font file actually supports
	weightMax: number; // equal to weightMin for a static/single-weight font
	faces: CustomFontFace[];
}

